"use strict";(self.webpackChunkm2c2_assessments_docs=self.webpackChunkm2c2_assessments_docs||[]).push([[653],{9948(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/m2c2-assessments/docs/","label":"Overview","docId":"index","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/common-parameters","label":"Common parameters","docId":"common-parameters","unlisted":false},{"type":"category","label":"Tasks","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/m2c2-assessments/docs/tasks/pvt-ba","label":"PVT-BA","docId":"tasks/pvt-ba","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/tasks/prices","label":"Prices","docId":"tasks/prices","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/tasks/fname","label":"FNAME","docId":"tasks/fname","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/tasks/fname-pairs","label":"FNAME-Pairs","docId":"tasks/fname-pairs","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/tasks/mvlt","label":"mVLT","docId":"tasks/mvlt","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/tasks/symbol-search","label":"Symbol Search","docId":"tasks/symbol-search","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/tasks/color-dots","label":"Color Dots","docId":"tasks/color-dots","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/tasks/grid-memory","label":"Grid Memory","docId":"tasks/grid-memory","unlisted":false},{"type":"link","href":"/m2c2-assessments/docs/tasks/color-shapes","label":"Color Shapes","docId":"tasks/color-shapes","unlisted":false}]}]},"docs":{"common-parameters":{"id":"common-parameters","title":"Common parameters","description":"These parameters are handled by each task\'s launch wrapper. Support varies slightly by task \u2014 the matrix below is derived from the wrapper source code.","sidebar":"docsSidebar"},"index":{"id":"index","title":"Overview","description":"Cognitive assessments hosted on GitHub Pages, built with m2c2kit. Every task is configured entirely through URL query parameters \u2014 this reference is generated from the task source code on every change, so it is always in sync with what is deployed.","sidebar":"docsSidebar"},"tasks/color-dots":{"id":"tasks/color-dots","title":"Color Dots","description":"A processing speed task from the m2c2kit library. Participants briefly see an array of colored dots, then after a short blank interval must recall the color of a specific dot. Measures speed and accuracy of color\u2013location binding.","sidebar":"docsSidebar"},"tasks/color-shapes":{"id":"tasks/color-shapes","title":"Color Shapes","description":"An executive function task from the m2c2kit library. Participants see colored shapes on a grid, then after a brief delay must judge whether the shapes have the same or different colors as before.","sidebar":"docsSidebar"},"tasks/fname":{"id":"tasks/fname","title":"FNAME","description":"A Face\u2013Name\u2013Occupation associative memory task. Participants learn face\u2013name and face\u2013occupation pairs, then must infer name\u2194occupation associations without seeing faces, and finally recognize correct pairings after a configurable delay.","sidebar":"docsSidebar"},"tasks/fname-pairs":{"id":"tasks/fname-pairs","title":"FNAME-Pairs","description":"A face\u2013name paired-associate memory task designed for sleep-dependent memory consolidation studies. Participants study 20 face\u2013name pairs from the Chicago Face Database, take an immediate cued-recall test, and \u2014 in a separate session launched hours later \u2014 a delayed cued-recall test on a deterministic seeded subset of the pairs. Pair identity, subsets, lure sets, and presentation orders are all reproducible from URL parameters.","sidebar":"docsSidebar"},"tasks/grid-memory":{"id":"tasks/grid-memory","title":"Grid Memory","description":"A spatial working memory task from the m2c2kit library. Participants see dots placed on a grid, perform an interference task, and then recall the dot locations from memory.","sidebar":"docsSidebar"},"tasks/mvlt":{"id":"tasks/mvlt","title":"mVLT","description":"A Mobile Verbal Learning Test. Participants study a list of 12 words, then perform a YES/NO recognition test on targets plus distractors. The study\u2013recognition cycle repeats to measure a within-person learning curve; d-prime is computed automatically.","sidebar":"docsSidebar"},"tasks/prices":{"id":"tasks/prices","title":"Prices","description":"An associative memory task with a learning and a recognition phase. Participants are shown item\u2013price pairs and asked to remember them, then tested on which price was paired with each item. Prices are localized to the participant\'s currency.","sidebar":"docsSidebar"},"tasks/pvt-ba":{"id":"tasks/pvt-ba","title":"PVT-BA","description":"An adaptive Psychomotor Vigilance Test that measures sustained attention and reaction time. A millisecond counter appears after a random delay; the participant taps the screen as quickly as possible. A Bayesian sequential algorithm classifies vigilance into HIGH, MEDIUM, or LOW, often terminating early once the posterior probability exceeds a decision threshold.","sidebar":"docsSidebar"},"tasks/symbol-search":{"id":"tasks/symbol-search","title":"Symbol Search","description":"A processing speed task from the m2c2kit library. Participants see a set of symbol pairs at the top of the screen and must quickly identify which of two bottom pairs matches one of the top pairs.","sidebar":"docsSidebar"}}}}')}}]);